:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #8a8fa3;
  --snake: #0f9b8e;
  --food: #e94560;
  --grid: #1f2b47;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.game-card {
  background: var(--card);
  border-radius: 16px;
  padding: 24px;
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.4);
  width: 100%;
  max-width: 480px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.game-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
}

h1 {
  font-size: 1.5rem;
  letter-spacing: 0.5px;
}

.score {
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--accent);
}

.board-wrap {
  position: relative;
  width: 100%;
  aspect-ratio: 1 / 1;
  border-radius: 8px;
  overflow: hidden;
  background: var(--grid);
}

canvas {
  display: block;
  width: 100%;
  height: 100%;
  image-rendering: pixelated;
}

.overlay {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(22, 33, 62, 0.92);
  padding: 24px;
  text-align: center;
  transition: opacity 0.2s ease;
}

.overlay.hidden {
  display: none;
}

.overlay-content {
  display: flex;
  flex-direction: column;
  gap: 16px;
  align-items: center;
  max-width: 320px;
}

.overlay h2 {
  font-size: 1.35rem;
}

.overlay p {
  line-height: 1.6;
  color: var(--muted);
}

.overlay p strong {
  color: var(--text);
}

.controls {
  display: flex;
  gap: 12px;
}

.btn {
  flex: 1;
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  padding: 12px 16px;
  border: 2px solid var(--accent);
  border-radius: 8px;
  background: transparent;
  color: var(--accent);
  cursor: pointer;
  transition: background 0.15s, color 0.15s, transform 0.05s;
}

.btn:hover {
  background: var(--accent);
  color: var(--card);
}

.btn:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 2px;
}

.btn:active {
  transform: scale(0.97);
}

.btn.primary {
  background: var(--accent);
  color: var(--card);
}

.btn.primary:hover {
  background: #f05a74;
  border-color: #f05a74;
}

.hint {
  font-size: 0.875rem;
  color: var(--muted);
  text-align: center;
}

@media (max-width: 400px) {
  .game-card {
    padding: 16px;
    gap: 12px;
  }
  h1 {
    font-size: 1.25rem;
  }
  .btn {
    padding: 10px 12px;
    font-size: 0.95rem;
  }
}

(function () {
  'use strict';

  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const scoreEl = document.getElementById('score');
  const overlay = document.getElementById('overlay');
  const overlayTitle = document.getElementById('overlay-title');
  const overlayText = document.getElementById('overlay-text');
  const overlayBtn = document.getElementById('overlay-btn');
  const pauseBtn = document.getElementById('pause-btn');
  const restartBtn = document.getElementById('restart-btn');

  const GRID = 20;
  const CELL = canvas.width / GRID;
  const TICK = 130;

  let snake, dir, nextDir, food, score, state, timer;
  // state: 'paused' | 'running' | 'over'

  function reset() {
    snake = [{ x: 10, y: 10 }, { x: 9, y: 10 }, { x: 8, y: 10 }];
    dir = { x: 1, y: 0 };
    nextDir = { x: 1, y: 0 };
    score = 0;
    scoreEl.textContent = '0';
    placeFood();
    state = 'paused';
    stopTimer();
    pauseBtn.textContent = 'Start';
    showOverlay('How to Play',
      'Use the <strong>arrow keys</strong> to move. Eat the red pixel to grow and score. Press <strong>Pause</strong> or <strong>Space</strong> to start.',
      'Start Game');
    draw();
  }

  function placeFood() {
    let pos;
    do {
      pos = { x: Math.floor(Math.random() * GRID), y: Math.floor(Math.random() * GRID) };
    } while (snake.some(s => s.x === pos.x && s.y === pos.y));
    food = pos;
  }

  function startTimer() {
    stopTimer();
    timer = setInterval(step, TICK);
  }

  function stopTimer() {
    if (timer) {
      clearInterval(timer);
      timer = null;
    }
  }

  function step() {
    dir = nextDir;
    const head = { x: snake[0].x + dir.x, y: snake[0].y + dir.y };

    if (head.x < 0 || head.x >= GRID || head.y < 0 || head.y >= GRID ||
        snake.some(s => s.x === head.x && s.y === head.y)) {
      gameOver();
      return;
    }

    snake.unshift(head);

    if (head.x === food.x && head.y === food.y) {
      score += 10;
      scoreEl.textContent = String(score);
      placeFood();
    } else {
      snake.pop();
    }

    draw();
  }

  function gameOver() {
    stopTimer();
    state = 'over';
    pauseBtn.textContent = 'Start';
    showOverlay('Game Over',
      'You scored <strong>' + score + '</strong> points. Press <strong>Restart</strong> to try again.',
      'Play Again');
  }

  function draw() {
    ctx.fillStyle = '#1f2b47';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.fillStyle = '#e94560';
    ctx.fillRect(food.x * CELL + 1, food.y * CELL + 1, CELL - 2, CELL - 2);

    snake.forEach((s, i) => {
      ctx.fillStyle = i === 0 ? '#0f9b8e' : '#0c7a70';
      ctx.fillRect(s.x * CELL + 1, s.y * CELL + 1, CELL - 2, CELL - 2);
    });
  }

  function showOverlay(title, html, btnLabel) {
    overlayTitle.textContent = title;
    overlayText.innerHTML = html;
    overlayBtn.textContent = btnLabel;
    overlay.classList.remove('hidden');
  }

  function hideOverlay() {
    overlay.classList.add('hidden');
  }

  function togglePause() {
    if (state === 'over') return;
    if (state === 'paused') {
      state = 'running';
      hideOverlay();
      pauseBtn.textContent = 'Pause';
      startTimer();
    } else {
      state = 'paused';
      stopTimer();
      pauseBtn.textContent = 'Resume';
      showOverlay('Paused', 'Press <strong>Resume</strong> or <strong>Space</strong> to continue.', 'Resume');
    }
  }

  function restart() {
    reset();
  }

  document.addEventListener('keydown', (e) => {
    if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', ' '].includes(e.key)) {
      e.preventDefault();
    }

    if (e.key === ' ') {
      togglePause();
      return;
    }

    if (state !== 'running') return;

    const map = {
      ArrowUp: { x: 0, y: -1 },
      ArrowDown: { x: 0, y: 1 },
      ArrowLeft: { x: -1, y: 0 },
      ArrowRight: { x: 1, y: 0 }
    };
    const nd = map[e.key];
    if (!nd) return;
    // prevent reversing
    if (nd.x === -dir.x && nd.y === -dir.y) return;
    nextDir = nd;
  });

  pauseBtn.addEventListener('click', togglePause);
  restartBtn.addEventListener('click', restart);
  overlayBtn.addEventListener('click', () => {
    if (state === 'over') restart();
    else togglePause();
  });

  reset();
})();
